#include <iostream>
#include <sstream>
#include <string>
#include <stack>
using namespace std;

int main() {
    string line;
    if (!getline(cin, line)) return 0;
    istringstream iss(line);
    stack<long long> st;
    string tok;

    while (iss >> tok) {
        if (tok == "+" || tok == "-" || tok == "*" || tok == "/") {
            long long b = st.top(); st.pop();   // 先弹出的是右操作数
            long long a = st.top(); st.pop();
            if (tok == "+") st.push(a + b);
            else if (tok == "-") st.push(a - b);
            else if (tok == "*") st.push(a * b);
            else st.push(a / b);
        } else {
            st.push(stoll(tok));
        }
    }
    cout << st.top() << "\n";
    return 0;
}
